const GT=372;
const A=PR._av,rect=A.rect,poly=A.poly,dot=A.dot,el=A.el,ar=A.ar,txt=A.txt,glow=A.glow,cl=A.cl,tn=A.tn;
const {P,fumo,fuoco,ln,md,mixs,tri,tavolo,candela}=PR._my;
const NOME="Pierpaolo";
