const nf=wx=>{if(wx<=NF[0][0])return NF[0][1];for(let i=1;i<NF.length;i++)if(wx<=NF[i][0]){const a=NF[i-1],b=NF[i];return a[1]+(b[1]-a[1])*(wx-a[0])/(b[0]-a[0])}return NF[NF.length-1][1]};
const SKY=[[0,['#5a5a8e','#e89a9a','#ffd8a8']],[Z[1]-300,['#8aa0c8','#d8d0d8','#f8ecd8']],[Z[2]+300,['#5a90d0','#a8c8e8','#e8f0f0']],[Z[3]+300,['#4a88d8','#90c4ec','#e0f0f8']],[Z[4]+300,['#58a0e0','#b8dcf0','#f4f0d8']],[Z[5]+300,['#6aa0d0','#e8d0a8','#ffe0a0']],[Z[6]-200,['#6a98c8','#f0c890','#ffd890']],[Z[6]+600,['#5a4a90','#e87860','#ffb868']],[Z[6]+1500,['#0a0e2a','#161c4a','#2a2a60']],[Z[7]-1500,['#0a0e2a','#161c4a','#2a2a60']],[Z[7]-300,['#3a4a88','#c07a90','#ffc890']],[Z[7]+100,['#000003','#02020a','#0a0a16']]];
